&lt;style&gt;
.aj-orders-page {
    padding: 30px 0 60px;
    color: #172033;
}

.aj-orders-heading {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
    margin-bottom: 25px;
}

.aj-orders-heading h2 {
    font-size: 27px;
    font-weight: 800;
    margin: 0;
}

.aj-orders-heading p {
    color: #64748b;
    font-size: 14px;
    margin: 6px 0 0;
}

.aj-order-card {
    background: #fff;
    border: 1px solid #e5eaf0;
    border-radius: 16px;
    margin-bottom: 20px;
    overflow: hidden;
    box-shadow: 0 5px 20px rgba(15, 23, 42, .035);
}

.aj-order-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
    padding: 18px 20px;
    background: #f8fafc;
    border-bottom: 1px solid #e8edf3;
}

.aj-order-number {
    font-size: 15px;
    font-weight: 800;
    color: #172033;
}

.aj-order-date {
    font-size: 12px;
    color: #64748b;
    margin-top: 5px;
}

.aj-status-badge {
    display: inline-flex;
    align-items: center;
    padding: 6px 11px;
    border-radius: 30px;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
}

.aj-status-success {
    background: #dcfce7;
    color: #166534;
}

.aj-status-warning {
    background: #fef3c7;
    color: #92400e;
}

.aj-status-primary {
    background: #dbeafe;
    color: #1d4ed8;
}

.aj-status-info {
    background: #cffafe;
    color: #155e75;
}

.aj-status-danger {
    background: #fee2e2;
    color: #991b1b;
}

.aj-status-secondary {
    background: #e2e8f0;
    color: #475569;
}

.aj-order-body {
    padding: 20px;
}

.aj-order-product {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 12px 0;
    border-bottom: 1px solid #f1f5f9;
}

.aj-order-product:last-child {
    border-bottom: 0;
}

.aj-order-product img {
    width: 68px;
    height: 68px;
    flex-shrink: 0;
    object-fit: contain;
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    padding: 5px;
}

.aj-product-name {
    font-size: 14px;
    font-weight: 700;
    color: #172033;
}

.aj-product-meta {
    color: #64748b;
    font-size: 12px;
    margin-top: 5px;
}

.aj-product-total {
    margin-left: auto;
    font-size: 14px;
    font-weight: 800;
    white-space: nowrap;
}

.aj-order-summary {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 15px;
    border-top: 1px solid #e8edf3;
    margin-top: 15px;
    padding-top: 18px;
}

.aj-summary-item small {
    display: block;
    color: #64748b;
    font-size: 11px;
    margin-bottom: 5px;
}

.aj-summary-item strong {
    font-size: 15px;
}

.aj-order-actions {
    display: flex;
    justify-content: flex-end;
    margin-top: 18px;
}

.aj-details-btn {
    border: 1px solid #dbe3ed;
    background: #fff;
    color: #334155;
    border-radius: 8px;
    padding: 9px 15px;
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
}

.aj-details-btn:hover {
    background: #f1f5f9;
}

.aj-order-details {
    display: none;
    padding: 18px 20px;
    background: #fbfdff;
    border-top: 1px solid #e8edf3;
}

.aj-order-details.aj-open {
    display: block;
}

.aj-details-title {
    font-size: 14px;
    font-weight: 800;
    margin: 0 0 13px;
}

.aj-shipment-box {
    border: 1px solid #e5eaf0;
    border-radius: 10px;
    padding: 13px;
    margin-top: 10px;
    background: #fff;
    font-size: 12px;
}

.aj-shipment-box strong {
    color: #172033;
}

.aj-empty-orders {
    text-align: center;
    background: #fff;
    padding: 65px 20px;
    border: 1px solid #e5eaf0;
    border-radius: 16px;
}

.aj-empty-orders i {
    font-size: 65px;
    color: #cbd5e1;
}

.aj-empty-orders h3 {
    font-size: 21px;
    font-weight: 800;
    margin: 15px 0 8px;
}

.aj-empty-orders p {
    color: #64748b;
    font-size: 14px;
}

.aj-shop-btn {
    display: inline-block;
    margin-top: 10px;
    padding: 12px 25px;
    border-radius: 30px;
    background: #16a34a;
    color: #fff !important;
    text-decoration: none;
    font-size: 13px;
    font-weight: 700;
}

@media(max-width: 576px) {
    .aj-orders-page {
        padding-top: 20px;
    }

    .aj-orders-heading h2 {
        font-size: 22px;
    }

    .aj-order-header {
        align-items: flex-start;
        padding: 14px;
    }

    .aj-order-body {
        padding: 14px;
    }

    .aj-order-product img {
        width: 58px;
        height: 58px;
    }

    .aj-product-name {
        font-size: 12px;
    }

    .aj-product-total {
        font-size: 12px;
    }

    .aj-order-summary {
        display: grid;
        grid-template-columns: 1fr 1fr;
    }

    .aj-order-details {
        padding: 15px;
    }
}
